import{_ as r,l as n,o as e,c as i,v as l,p as s,x as t,d as p,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"范数、余弦与投影","description":"","frontmatter":{"title":"范数、余弦与投影","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/norm-cosine-projection.md","filePath":"llm/norm-cosine-projection.md","lastUpdated":1789023840000}'),_={name:"llm/norm-cosine-projection.md"};function h(u,a,c,E,f,x){const o=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=l('<h1 id="范数、余弦与投影" tabindex="-1">范数、余弦与投影 <a class="header-anchor" href="#范数、余弦与投影" aria-label="Permalink to &quot;范数、余弦与投影&quot;">​</a></h1><div class="epigraph"><p>两个向量是否「像」，要先说清用哪种长度；夹角与投影是同一套内积里的不同读数。</p><footer>—— 据 Goodfellow, Bengio &amp; Courville, Deep Learning, 2016；Strang, Linear Algebra and Its Applications 整理</footer></div><p><a href="/llm/matmul-as-layer">矩阵乘作为一层</a>给出 \\(y=xW^\\top\\)，把向量从一个坐标送到另一个坐标。本课不重推这次乘法。缺口是：送到新空间之后，如何度量长度、夹角、以及「落在某一方向上的分量」。后面的 softmax 打分、注意力里的点积、层归一化里的除标准差，都要先有范数与内积，否则分数只是一堆无单位的数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>线性层输出一组坐标，但训练目标很少直接比较原始坐标。分类要的是「谁更像某一类的方向」，检索要的是「两段表示夹角小不大」，归一化要的是「把长度拉到固定尺度」。若只用逐维相减的平方和，尺度大的向量永远「更远」，即使方向一致。缺口因此不是再做一次矩阵乘，而是在已经对齐的 \\(\\mathbb{R}^d\\) 上引入长度与角度。</p><p>内积 \\(\\langle u,v\\rangle=u^\\top v\\) 同时给出三件事：自身内积是欧氏范数的平方；除以两范数得到余弦；固定一个方向 \\(u\\) 时，\\(\\langle u,v\\rangle\\) 是 \\(v\\) 在该方向上的（未归一）投影系数。后课把「打分」写成内积，把「相似」写成余弦，把「去掉长度」写成除范数——本课把这三种读数一次分清。</p><h3 id="余弦不是另一种距离公式" tabindex="-1">余弦不是另一种距离公式 <a class="header-anchor" href="#余弦不是另一种距离公式" aria-label="Permalink to &quot;余弦不是另一种距离公式&quot;">​</a></h3><p>欧氏距离 \\(\\|u-v\\|_2\\) 对平移和尺度都敏感。余弦 \\(\\langle u,v\\rangle/(\\|u\\|_2\\|v\\|_2)\\) 只看方向，把长度除掉。两者不是同一度量换写法。把词向量里「相近」理解成欧氏最近邻，会把高频词（往往更长）和低频词系统性地分开；理解成余弦，才是在比方向。后课嵌入几何默认比的是角，除非明确说用欧氏。</p><p><span class="marginnote">\\(\\ell_2\\) 范数 \\(\\|x\\|_2=\\sqrt{\\sum_i x_i^2}\\) 是本课默认长度。\\(\\ell_1\\)、\\(\\ell_\\infty\\) 在稀疏与对抗里会出现，本课不切换。投影是 \\(\\mathrm{proj}_u v=\\frac{\\langle u,v\\rangle}{\\langle u,u\\rangle}u\\)，系数是标量，结果仍是向量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对 \\(x\\in\\mathbb{R}^d\\)，欧氏范数 \\(\\|x\\|_2\\)。单位向量 \\(\\hat x=x/\\|x\\|_2\\)（零向量除外）。两向量余弦 \\(\\cos\\theta=\\langle u,v\\rangle/(\\|u\\|_2\\|v\\|_2)\\in[-1,1]\\)。未归一的点积 \\(\\langle u,v\\rangle=\\|u\\|_2\\|v\\|_2\\cos\\theta\\)，因此点积同时含长度与夹角：两向量都变长，点积变大，即使角不变。</p><p>一批向量 \\(X\\in\\mathbb{R}^{B\\times d}\\) 的两两余弦，是先按行除范数，再做 \\(XX^\\top\\)。这与上一课的矩阵乘是同一算子，收缩的是特征维 \\(d\\)。本课不把这一步叫成注意力：没有查询键的线性投影，也没有按行的 softmax。只是「同一套 GEMM 可以读成相似度矩阵」。</p>',12)),(e(),s(m,null,{default:t(()=>[d(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E5%90%91%E9%87%8F%20u%22%5D%20--%3E%20DOT%5B%22%E5%86%85%E7%A7%AF%22%5D%0A%20%20V%5B%22%E5%90%91%E9%87%8F%20v%22%5D%20--%3E%20DOT%0A%20%20DOT%20--%3E%20LEN%5B%22%E8%8C%83%E6%95%B0%E6%9D%A5%E8%87%AA%E8%87%AA%E5%86%85%E7%A7%AF%22%5D%0A%20%20DOT%20--%3E%20COS%5B%22%E4%BD%99%E5%BC%A6%E9%99%A4%E6%8E%89%E4%B8%A4%E8%8C%83%E6%95%B0%22%5D%0A%20%20DOT%20--%3E%20PROJ%5B%22%E6%8A%95%E5%BD%B1%E7%B3%BB%E6%95%B0%E7%95%99%E5%9C%A8%20u%20%E6%96%B9%E5%90%91%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>训练里经常先去掉长度再比方向，因为长度容易被层的尺度、初始化、学习率带跑，方向才编码「像哪一类」。层归一化稍后会在特征维上减均值、除标准差，那是把每个位置的向量拉到相近的范数量级；本课的除范数是更粗的版本，只处理长度，不处理各维的偏移。</p><p>点积作为打分函数的隐患也在这里：若不确定 \\(\\|q\\|\\) 与 \\(\\|k\\|\\) 的尺度，同一夹角会给出差几个数量级的分数，后面的 softmax 会饱和。本课只指出这个乘法结构；如何在指数之前减最大值、如何除 \\(\\sqrt{d}\\)，分别是后课 softmax 与（更后面的）缩放点积的缺口，这里不提前讲完。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入马氏距离、核技巧，也不把 PCA 投影当成一层网络。下一课<a href="/llm/softmax-numerics">Softmax 与数值稳定</a>把一组无约束的打分变成单纯形上的概率；那些打分可以是点积，但本课不把 softmax 写出来。后课默认：说到两个向量「像」，先声明是余弦还是点积；说到「长度」，默认 \\(\\ell_2\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内积同时给出长度、余弦与沿一方向的投影系数。</li><li>余弦去掉尺度，只比方向；点积保留长度，尺度会污染分数。</li><li>按行归一再做 \\(XX^\\top\\) 是相似度矩阵，还不是注意力。</li><li>后课 softmax 吃的是这组分数；分数尺度过大将在指数上饱和。</li><li>出处：Goodfellow et al., Deep Learning, 2016；Strang 对内积与投影的处理。</li></ul>',7))])}const B=r(_,[["render",h]]);export{g as __pageData,B as default};
